let my_dm_interval;
const my_dm_target = document.querySelector('[aria-label^="Chat"]');
const my_dm_notification_1 =
  "data:audio/wav;base64,"
const my_dm_notification_2 =
  "data:audio/wav;base64,"

let my_dm_count = 0;
let my_dm_audio_test = false;
let my_dm_slow = false;
let my_dm_fast = false;
let my_dm_override = false;
const my_dm_scan_interval = 5000;
const my_dm_slow_interval = 1000;//my_dm_notification1.duration * 1000;

//Seemsless audio
const my_dm_audio_ctx_1 = new window.AudioContext();
const my_dm_audio_ctx_2 = new window.AudioContext();
const my_dm_source_1 = my_dm_audio_ctx_1.createBufferSource();
const my_dm_source_2 = my_dm_audio_ctx_2.createBufferSource();
const my_dm_array_buffer_notification_1 = await fetch(
  my_dm_notification_1,
).then((res) => res.arrayBuffer());
const my_dm_array_buffer_notification_2 = await fetch(
  my_dm_notification_2,
).then((res) => res.arrayBuffer());

const my_dm_audio_buffer_1 = await my_dm_audio_ctx_1.decodeAudioData(my_dm_array_buffer_notification_1);
my_dm_source_1.buffer = my_dm_audio_buffer_1;
const my_dm_audio_buffer_2 = await my_dm_audio_ctx_2.decodeAudioData(my_dm_array_buffer_notification_2);
my_dm_source_2.buffer = my_dm_audio_buffer_2;

my_dm_source_1.loop = true;
my_dm_source_2.loop = true;
my_dm_source_1.connect(my_dm_audio_ctx_1.destination);
my_dm_source_2.connect(my_dm_audio_ctx_2.destination);
my_dm_source_1.start();
await my_dm_audio_ctx_1.suspend();
my_dm_source_2.start();
await my_dm_audio_ctx_2.suspend();



async function my_dm_notif_function() {
  if (
    (my_dm_target !== null && my_dm_target?.childElementCount > 1) ||
    my_dm_audio_test) {
    // console.log(my_adm_count)
    if (my_dm_audio_test && my_dm_count == 0) my_dm_count = 12;
    if (my_dm_audio_test && my_dm_count == 20) my_dm_count = 55;

    if (my_dm_count > 12 && my_dm_count < 62) {
      if (!my_dm_slow) {
        my_dm_slow = true;
        clearInterval(my_dm_interval);
        my_dm_interval = setInterval(my_dm_notif_function, my_dm_slow_interval);
        if (!my_dm_override) {
          await my_dm_audio_ctx_1.resume();
        }
      }
      if (my_dm_override) {
        await my_dm_audio_ctx_1.suspend();
      }
    } else if (my_dm_count >= 62) {
      if (!my_dm_fast) {
        await my_dm_audio_ctx_1.suspend();
        my_dm_fast = true;
        if (!my_dm_override) {
          await my_dm_audio_ctx_2.resume();
        }
      }
      if (my_dm_override) {
        await my_dm_audio_ctx_2.suspend();
      }
    }
    my_dm_count++;
  } else {
    my_dm_override = false;

    if (my_dm_slow || my_dm_fast) {
      if (my_dm_slow) {
        await my_dm_audio_ctx_1.suspend();
      }
      if (my_dm_fast) {
        await my_dm_audio_ctx_2.suspend();
      }
      my_dm_slow = false;
      my_dm_fast = false;
      clearInterval(my_dm_interval);
      my_dm_interval = setInterval(my_dm_notif_function, my_dm_scan_interval);
    }
    my_dm_count = 0;
  }
}

my_dm_interval = setInterval(my_dm_notif_function, my_dm_scan_interval);
